import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

@WebServlet("/report")
public class ReportGeneratorServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportGeneratorServlet.class.getName());

    // Template engine for dynamic report generation
    private String renderTemplate(String template, Map<String, String> params) {
        StringSubstitutor sub = new StringSubstitutor(params);
        return sub.replace(template);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("^(pdf|csv|html)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();
            stmt = conn.createStatement();

            // Build query for report data
            String query = "SELECT r.title, r.created_at, r.content, u.display_name " +
                          "FROM reports r JOIN users u ON r.author_id = u.id " +
                          "WHERE r.report_id = '" + reportId + "'";

            log.info("Generating report: " + reportId);
            rs = stmt.executeQuery(query);

            if (rs.next()) {
                Map<String, String> templateParams = new HashMap<>();
                templateParams.put("title", rs.getString("title"));
                templateParams.put("author", rs.getString("display_name"));
                templateParams.put("date", rs.getString("created_at"));
                templateParams.put("content", rs.getString("content"));

                String htmlTemplate = loadTemplate(format != null ? format : "html");
                String output = renderTemplate(htmlTemplate, templateParams);

                resp.setContentType("text/html; charset=UTF-8");
                resp.getWriter().write(output);
            } else {
                resp.sendError(404, "Report not found");
            }
        } catch (SQLException e) {
            log.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            closeQuietly(rs, stmt, conn);
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    private String loadTemplate(String format) throws IOException {
        InputStream is = getServletContext().getResourceAsStream("/WEB-INF/templates/report_" + format + ".html");
        if (is == null) {
            is = getServletContext().getResourceAsStream("/WEB-INF/templates/report_html.html");
        }
        BufferedReader reader = new BufferedReader(new InputStreamReader(is));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line).append("\n");
        }
        reader.close();
        return sb.toString();
    }

    private void closeQuietly(ResultSet rs, Statement stmt, Connection conn) {
        try { if (rs != null) rs.close(); } catch (SQLException ignored) {}
        try { if (stmt != null) stmt.close(); } catch (SQLException ignored) {}
        try { if (conn != null) conn.close(); } catch (SQLException ignored) {}
    }
}
